test('D5 - Tunneling: Ball should not pass through brick at high speed', () => {
  const state = createState(6); // Speed = 710
  const brick = state.bricks[0];

  // Position ball just above the brick
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y - 10; 
  state.ball.vy = 710; 
  state.ball.vx = 0;

  // Move ball by 0.05s (the cap)
  // New position: y = brick.y - 10 + 710 * 0.05 = brick.y - 10 + 35.5 = brick.y + 25.5
  // The brick height is 20. So ball.y - ball.r = brick.y + 25.5 - 7 = brick.y + 18.5.
  // Wait, 18.5 is still inside the brick (brick.y + 20).
  // Let's make it faster or dt larger.

  state.ball.vy = 1000; // Very fast
  // New position: y = brick.y - 10 + 1000 * 0.05 = brick.y + 40.
  // Ball.y - ball.r = brick.y + 40 - 7 = brick.y + 33.
  // Now it's completely BELOW the brick (brick.y + 20).

  // Simulate a frame
  // In the real game: step(state, 0.05) then frame(ctx, state)
  const dt = 0.05;
  const oldBall = { ...state.ball };

  // Manual step
  state.ball.x += state.ball.vx * dt;
  state.ball.y += state.ball.vy * dt;

  frame(mockCtx, state);

  assert.ok(!brick.alive, 'Brick should have been destroyed');
  assert.ok(state.ball.vy < 0, 'Ball should have bounced UP');
});

